"""Compile independently authored teaching records into the app's portable content format.
No third-party article, transcript, quiz or audio is copied.
"""
import json,pathlib
ROOT=pathlib.Path(__file__).resolve().parents[2]
SYLLABUS=json.loads((ROOT/'content/syllabus.json').read_text())
def emit(course,rows):
 for row in rows:
  n,subtitle,objectives,lectures,reading,worked,phrases,task,culture,resource=row
  uid=f'c{course}-u{n:02}';sy=SYLLABUS[course-1]['units'][n-1]
  pairs=[p.split('|') for p in phrases.split(';')]
  assert len(pairs)>=15,(uid,len(pairs))
  w=[dict(prompt=p,answer=a,reason=r) for p,a,r in worked]
  qs=[dict(id=f'{uid}-q{i:02}',type='cloze' if '___' in x['prompt'] else 'typed',prompt=x['prompt'],answers=x['answer'].split(' / '),explanation=x['reason'],concept=lectures[0][0] if i<=3 else lectures[-1][0]) for i,x in enumerate(w,1)]
  for j,(es,en) in enumerate(pairs[:6],7):
   others=[pairs[(j+1)%len(pairs)],pairs[(j+5)%len(pairs)]]
   opts=[es,*[x[0] for x in others]]
   if len(set(opts))<3:opts=[es,*[x[0] for x in pairs if x[0]!=es][:2]]
   offset=j%3;opts=opts[offset:]+opts[:offset]
   qs.append(dict(id=f'{uid}-q{j:02}',type='choice' if j%2 else 'matching',prompt=f'Choose the expression that communicates this meaning: {en}.',options=opts,answers=[es],explanation=f'“{es}” expresses “{en}”. '+ ' '.join(f'“{o}” instead means “{dict(pairs)[o]}”.' for o in opts if o!=es),concept='Meaning and register'))
  unit=dict(id=uid,course=course,number=n,title=sy['title'],subtitle=subtitle,status='authored',prerequisites=sy['prerequisites'],objectives=objectives,warmup=f'Retrieve two sentences and one repair strategy from {sy["prerequisites"][0]}. Change the subject or situation in each sentence and explain what changed. Then read today’s objectives and predict where your existing language may be insufficient.',lectures=[dict(title=t,body=b) for t,b in lectures],reading=reading,worked=w,cards=[dict(id=f'{uid}-f{i:02}',unit=uid,kind='production' if i%2 else 'recognition',front=en if i%2 else es,back=es if i%2 else en,example=es) for i,(es,en) in enumerate(pairs,1)],quiz=qs,homework=[
   dict(id=f'{uid}-h1',skill='Reading & writing',prompt=f'Read the original text for this unit. Identify its situation, central message, and three supporting details. Then write a new version of {100 if course==2 else 150 if course==3 else 220 if course==4 else 300}–{140 if course==2 else 200 if course==3 else 280 if course==4 else 400} words for a different person or audience. Use the target patterns, change at least three facts, and explain two revisions.',model=reading+'\n\nThis is the source model, not a text to submit unchanged. A successful adaptation retains the communicative purpose while changing relevant forms and facts. Compare with the worked examples for the reasons behind form choices.',rubric='0–3 each: fulfills the specified purpose; organized and comprehensible; target forms support meaning; revisions are explained with examples. 0 = no evidence, 1 = substantial help needed, 2 = effective with some support, 3 = independently effective for this task. Record who evaluated the work.'),
   dict(id=f'{uid}-h2',skill='Listening',prompt='Complete the resource assignment, or ask a willing reader to read the original text without showing it to you. First listen for the situation and purpose; listen again for three details and one contrast. Write a 60–100-word listening log naming the source, words actually heard, one uncertainty, and how you checked it. If using local synthesized speech, label it synthetic. Text-only preparation is not completed listening.',model='A useful log separates the speaker’s message from your interpretation: “I heard [specific phrase]; I understood [claim]; I was uncertain about [word/relationship]; checking [text or partner] changed my interpretation to [correction].” Use the unit reading as an answer reference for a read-aloud version, never as evidence of an external speaker’s words.',rubric='0–2 each: identifies source and listening conditions; retrieves central meaning; supports three details; checks a specific uncertainty. Do not count a copied transcript as independent comprehension.'),
   dict(id=f'{uid}-h3',skill='Speaking & interaction',prompt=task,model='Use the original reading/dialogue and the sentence-pattern cards as preparation. Make a brief outline, then put it away. Your partner should introduce a detail you did not prepare. Respond, request clarification if needed, and summarize what you agreed or still disagree about. Solo fallback: record two possible viewpoints and improvise a response after a pause; label it rehearsal.',rubric='0–3 each: task fulfillment, comprehensibility, control of target language, responsiveness to another speaker. A partner or instructor should cite one example per score. Solo rehearsal provides no evidence for live responsiveness; mark that dimension not observed.'),
   dict(id=f'{uid}-h4',skill='Retrieval & reflection',prompt='On a later day, retrieve six cards without looking. Use three in a fresh response to the practical task. Identify one recurring form error and one communication difficulty. Produce a corrected example, explain the reason, and schedule a specific follow-up exchange or listening session.',model=f'Compare your response with these two models: {pairs[0][0]} / {pairs[1][0]}. A useful reflection explains the function, not just the spelling. Revisit the first worked item and create a different example of its principle.',rubric='Report recall count separately from performance. Reflection is complete when it contains an observed difficulty, an explained correction, a fresh example, and an actionable next session.')],task=task,culture=culture,selfAssessment=['I can '+o[0].lower()+o[1:].rstrip('.')+'.' for o in objectives],remediation='Sort mistakes by form, meaning, and interaction. For form errors, explain a worked example and create a contrasting pair. For comprehension errors, replay a short segment or use a willing reader and verify your interpretation. For interaction difficulties, repeat the practical task with one new constraint. Compare evidence across days; repeated selection of a known answer alone is not mastery.',resources=[resource])
  selected=[c for c in unit['cards'] if c['kind']=='production'][2:5]
  matching=unit['quiz'][-1]
  matching.update(prompt='Match each English meaning to its Spanish expression. Use each expression once.',pairs=[{'left':c['front'],'right':c['back']} for c in selected],answers=[json.dumps([c['back'] for c in selected],ensure_ascii=False,separators=(',',':'))],explanation=' '.join('“'+c['back']+'” means “'+c['front']+'”.' for c in selected)+' Each alternative belongs to a different meaning; check the whole phrase, including its grammatical person and register.')
  matching.pop('options',None)
  (ROOT/f'content/units/{uid}.json').write_text(json.dumps(unit,ensure_ascii=False,indent=2)+'\n')
  SYLLABUS[course-1]['units'][n-1]['status']='authored'
 (ROOT/'content/syllabus.json').write_text(json.dumps(SYLLABUS,ensure_ascii=False,indent=2)+'\n')
 print(f'Authored course {course}: {len(rows)} units')
